={{ (() => {
  const mensajeOriginal = $fromAI('mensaje_original', 'Copia LITERAL y completa, palabra por palabra, la parte del mensaje del usuario donde menciona el identificador del animal (arete, número de fuego o RFID). No resumas, no reescribas, no interpretes — pega el texto tal cual.', 'string') || '';
  const identificadorLLM = ($fromAI('identificador', 'El identificador del animal (arete SINIIGA o número de fuego o RFID/electronic_rfid — chip o bolo ruminal). Usa el valor que el usuario haya proporcionado', 'string') || '').trim();

  // Collapse only Whisper-style dictation (single digits separated by spaces, e.g. "9 9 9 8 8"),
  // never whole numbers: "0715690333 50 g" must stay two separate numbers.
  const normalizado = mensajeOriginal.replace(/\b\d(?:\s+\d\b){2,}/g, (m) => m.replace(/\s+/g, ''));
  const corridas = normalizado.match(/\d{6,}/g) || [];

  // Tie-break: trust the LLM value when it appears verbatim as a whole number in the message;
  // fall back to the deterministic run only when it does not (e.g. a dropped digit).
  const llmEnMensaje = identificadorLLM !== '' && corridas.includes(identificadorLLM);
  const identificadorDeterministico = (corridas.length === 1 && corridas[0].length <= 15) ? corridas[0] : null;

  return [
    llmEnMensaje ? identificadorLLM : (identificadorDeterministico || identificadorLLM),
    $fromAI('tenant_id', 'ID del rancho / tenant_id actual del usuario', 'number'),
    $fromAI('user_email', 'Copia el email del usuario EXACTAMENTE carácter por carácter desde el contexto de sesión (system prompt) — nunca lo reescribas de memoria ni lo abrevies. Antes de usarlo, cuenta que tenga el mismo número de caracteres que el original. Un solo carácter de diferencia hace que el sistema no encuentre ningún dato, sin mostrar ningún error.', 'string')
  ];
})() }}

